# generated by tools/ail2py.py from directory_catalog.ail; edit the .ail until onelang s16
from json_text import *
from ail import is_dir, list_dir, path_exists
# A sorted, nonrecursive snapshot; metadata is queried after enumerating names.
def directory_catalog(path: str) -> str:
    names: list[str] = list_dir(path)
    ordered = sorted(names)
    records: list[str] = []
    for name in ordered:
        entry_path = path + '/' + name
        records.append('{"name":' + json_quote(name) + ',"directory":' + str(is_dir(entry_path)) + ',"exists":' + str(path_exists(entry_path)) + '}')
    return '[' + ','.join(records) + ']'
